   return heroMarkup+categoryMarkup+featured(produce.length?produce:products.slice(0,8),"Fresh picks for your table","THE PRODUCE EDIT","Browse produce and farm-led staples from the current catalogue.")+provenance;
 }
 if(template==="express-grocery"){
