function quickOrderSheet(limit=150){const rows=activeProducts().slice(0,Math.max(1,Math.min(150,Number(limit)||150))).map(p=>'<tr data-bulk-row data-bulk-name="'+esc((p.name+" "+(p.sku||"")).toLowerCase())+'"><td>'+esc(p.name)+'<br><small>'+esc(p.sku||"No SKU")+'</small></td><td>'+money(priceForProduct(p,1))+' / '+esc(p.unit||"unit")+(state.priceTiers.some(t=>t.product_id===p.id)?'<br><small>Volume pricing available</small>':"")+'</td><td>'+Number(p.stock).toLocaleString("en-BD")+'</td><td><input class="sf-bulk-qty" type="number" min="0" max="'+Number(p.stock)+'" step="any" value="0" data-bulk-qty="'+esc(p.id)+'" aria-label="Quantity for '+esc(p.name)+'" '+(Number(p.stock)<=0?"disabled":"")+'></td></tr>').join("");return '<section class="sf-section"><div class="sf-section-head"><div><span class="sf-kicker">BUSINESS BUYING</span><h2>Quick bulk order sheet</h2><p>Enter quantities for multiple products, then add them to one basket. Volume prices are applied automatically.</p></div></div><div class="sf-toolbar"><input class="sf-sort" id="sfBulkSearch" type="search" placeholder="Find a product or SKU…" aria-label="Find a bulk product"></div><form id="sfBulkQuickOrder"><div class="sf-table-wrap"><table class="sf-table"><thead><tr><th>Product</th><th>Unit price</th><th>Available</th><th>Quantity</th></tr></thead><tbody>'+(rows||'<tr><td colspan="4">No active products are available.</td></tr>')+'</tbody></table></div><div class="sf-blog-end"><button class="sf-btn" type="submit" '+(rows?"":"disabled")+'>Add selected products to basket</button><a class="sf-btn secondary" href="'+pageUrl("cart")+'">Review basket</a></div><p id="sfBulkQuickStatus" class="sf-help" role="status" aria-live="polite"></p></form></section>';}
function bulkEnquiryPage(){return pageHead("BUSINESS CUSTOMERS","Bulk & business enquiry","Request a formal supply quotation. Your enquiry is saved securely for the store team to review.")+quickOrderSheet()+'<form class="sf-form-card" id="sfBulkEnquiry"><div class="sf-form-grid"><div class="sf-field"><label for="sfBulkCompany">Business / company name *</label><input id="sfBulkCompany" name="company_name" required maxlength="180"></div><div class="sf-field"><label for="sfBulkContact">Contact person *</label><input id="sfBulkContact" name="contact_name" required maxlength="160"></div><div class="sf-field"><label for="sfBulkPhone">Business phone *</label><input id="sfBulkPhone" name="phone" required inputmode="tel" maxlength="24"></div><div class="sf-field"><label for="sfBulkEmail">Business email</label><input id="sfBulkEmail" name="email" type="email" maxlength="254"></div><div class="sf-field"><label for="sfBulkType">Business type</label><select id="sfBulkType" name="business_type"><option value="">Choose business type</option><option>Retail shop</option><option>Restaurant / café</option><option>Caterer</option><option>Institution</option><option>Distributor</option><option>Other</option></select></div><div class="sf-field"><label for="sfBulkTax">Tax / business ID</label><input id="sfBulkTax" name="tax_id" maxlength="100"></div><div class="sf-field full"><label for="sfBulkNeed">Products, pack sizes and quantities *</label><textarea id="sfBulkNeed" name="message" required minlength="5" maxlength="4000" placeholder="Example: Premium rice 25 kg × 20 bags&#10;Cooking oil 5 L × 12 cartons"></textarea></div><div class="sf-field full"><button class="sf-btn" id="sfBulkSubmit" type="submit">Submit quote request</button><small id="sfBulkStatus" role="status"></small></div></div></form>';}function returnsPage(){return pageHead("ORDER SUPPORT","Returns & refunds","Submit a return request for an order that has already been delivered. The store will review it and contact you.")+'<