function renderShell(){const brand=state.website.brand?.name||templateInfo[state.website.template_key]?.brand||state.website.name;const nav=[["home","Home"],["shop","Shop"],["offers","Offers"],["brands","Brands"],["recipes","Recipes"],["journal","Journal"],["about","Our story"],["store-locator","Find a store"],["delivery","Delivery"],["faq","FAQs"],["bulk-enquiry","Business"],["contact","Contact"],["order-tracking","Track order"]];const demoMode=Boolean(state.website.settings?.demo_catalog),sampleCatalogue=demoMode||state.products.some(p=>Boolean(p.attributes?.demo)||!Boolean(p.attributes?.inventory_verified));return (preview&&!demoMode?'<div class="sf-preview-bar"><strong>PRIVATE PREVIEW</strong> · This site is not public. Orders cannot be placed until it is published.</div>':demoMode?'<div class="sf-preview-bar"><strong>DEMO STOREFRONT</strong> · Explore the complete shopping experience. Test orders are labelled DEMO and do not reserve real inventory.</div>':'')+(demoMode?'<div class="sf-catalogue-notice" role="status"><strong>DEMO CATALOGUE</strong><span>Add products to your basket, check out and submit test orders. Demo orders will appear in the owner dashboard.</span></div>':sampleCatalogue?'<div class="sf-catalogue-notice" role="status"><strong>Catalogue preview</strong><span>Some products or stock details are sample/unverified. Ordering remains disabled until the store verifies its catalogue.</span></div>':'')+'<div class="sf-announcement">'+esc(state.website.brand?.announcement||"Thoughtful shopping · Reliable local service")+'</div><header class="sf-header"><div class="sf-header-inner"><a class="sf-brand" href="'+pageUrl("home")+'"><span class="sf-brand-mark">'+esc(brand.slice(0,2).toUpperCase())+'</span><span class="sf-brand-copy"><strong>'+esc(brand)+'</strong><small>'+esc(templateInfo[state.website.template_key]?.eyebrow||"ONLINE STORE")+'</small></span></a><form class="sf-search" id="sfHeaderSearch" role="search"><span>⌕</span><input name="q" placeholde