function searchSuggestions(query){const box=root.querySelector("#sfSearchSuggestions");if(!box)return;const q=String(query||"").trim().toLowerCase();if(!q){box.hidden=true;box.innerHTML="";return;}const matches=state.products.filter(p=>[p.name,p.sku,p.attributes?.brand,p.attributes?.origin,categoryName(p)].join(" ").toLowerCase().includes(q)).slice(0,6);box.innerHTML=matches.length?matches.map(p=>'<a class="sf-search-suggestion" href="'+pageUrl("product",{product:p.id})+'">'+(imageUrl(p)?'<img src="'+esc(imageUrl(p))+'" alt="" loading="lazy">':'<span class="sf-search-suggestion-fallback">'+esc(p.name.slice(0,1))+'</span>')+'<span><strong>'+esc(p.name)+'</strong><small>'+esc(categoryName(p))+' · '+money(p.price)+'</small></span><span class="sf-search-suggestion-arrow">↗</span></a>').join(""):'<div class="sf-search-no-results">No matching products. Press Enter to search the full catalogue.</div>';box.hidden=false;}
function render(){const brand=state.website.brand||{},template=state.website.template_key;document.body.dataset.template=template;document.title=(pageTitles[state.page]||"Store")+" · "+(brand.name||templateInfo[template]?.brand||state.website.name);const main=renderPage();root.innerHTML=renderShell()+'<main class="sf-main">'+main+'</main>'+renderFooter()+mobileDock();bind();}
function bind(){root.querySelector("#sfMenuToggle")?.addEventListener("click",()=>{state.mobileMenu=!state.mobileMenu;root.querySelector("#sfNav")?.classList.toggle("is-open",state.mobileMenu);root.querySelector("#sfMenuToggle")?.setAttribute("aria-expanded",String(state.mobileMenu));});root.querySelector("#sfHeaderSearch")?.addEventListener("submit",e=>{e.preventDefault();const q=new FormData(e.currentTarget).get("q")||"";location.href=pageUrl("search",{q});});root.querySelector("#sfHeaderSearch input[name=q]")?.addEventListener("input",e=>searchSuggestions(e.target.value));root.querySelector("#sfHeaderSearch input[name=q]")?.addEventListener("keydown",e=>{if(e.key==="Escape"){const box=root.querySelector("#sfSearchSuggestions");if(box)box.hidden=true;}});root.querySelector("#sfSearchForm")?.addEventListener("submit",e=>{e.preventDefault();const q=new FormData(e.currentTarget).get("q")||"";location.href=pageUrl("search",{q});});root.querySelector("#sfSort")?.addEventListener("change",e=>{state.filters.sort=e.target.value;const el=root.querySelector("#sfProductResults");if(el)el.innerHTML=productGrid(filteredProducts());bindDynamic();});root.querySelector("#sfBrandFilter")?.addEventListener("change",e=>{state.filters.brand=e.target.value;const el=root.querySelector("#sfProductResults");if(el)el.innerHTML=productGrid(filteredProducts());bindDynamic();});root.querySelector("#sfAvailabilityFilter")?.addEventListener("change",e=>{state.filters.availability=e.target.value;const el=root.querySelector("#sfProductResults");if(el)el.innerHTML=productGrid(filteredProducts());bindDynamic();});root.querySelector("#sfCheckoutForm")?.addEventListener("submit",submitOrder);root.querySelector("#sfArea")?.addEventListener("change",updateCheckoutSummary);root.querySelector("#sfTrackForm")?.addEventListener("submit",trackOrder);root.querySelector("#sfReturnForm")?.addEventListener("submit",submitReturnRequest);root.querySelector("#sfBulkQuickOrder")?.addEventListener("submit",submitBulkQuickOrder);root.querySelector("#sfBulkSearch")?.addEventListener("input",e=>{const q=e.target.value.toLowerCase();root.querySelectorAll("[data-bulk-row]").forEach(row=>row.hidden=!row.dataset.bulkName.includes(q));});root.querySelector("#sfBulkEnquiry")?.addEventListener("submit",submitQuote);bindDynamic();}
function bindDynamic(){root.querySelectorAll('[data-reorder-tracked]').forEach(b=>b.addEventListener('click',reorderTrackedOrder));root.querySelectorAll("[data-add]").forEach(b=>b.addEventListener("click",()=>addToCart(b.dataset.add)));root.querySelectorAll("[data-buy-now]").forEach(b=>b.addEventListener("click",()=>{addToCart(b.dataset.buyNow,Number(root.querySelector("#sfProductQty")?.value)||1,true);}));root.querySelectorAll("[data-wish]").forEach(b=>b.addEventListener("click",()=>toggleWish(b.dataset.wish)));root.querySelectorAll("[data-filter-category]").forEach(b=>b.addEventListener("click",()=>{state.filters.category=b.dataset.filterCategory;const el=root.querySelector("#sfProductResults");if(el)el.innerHTML=productGrid(filteredProducts());root.querySelectorAll("[data-filter-category]").forEach(x=>x.classList.toggle("is-active",x===b));bindDynamic();}));root.querySelectorAll("[data-cart-qty]").forEach(b=>b.addEventListener("click",()=>{const p=getProduct(b.dataset.product);changeCart(b.dataset.product,Number(b.dataset.cartQty)*(p?quantityStep(p):1));}));root.querySelectorAll("[data-cart-input]").forEach(input=>input.addEventListener("change",()=>{const p=getProduct(input.dataset.product),row=state.cart.find(x=>x.product_id===input.dataset.product);if(!p||!row)return;const value=Number(input.value),minimum=quantityMinimum(p);if(!Number.isFinite(value)||value<minimum||value>Number(p.stock)){notify("Enter a quantity between "+minimum+" and "+Number(p.stock)+".");render();return;}row.quantity=value;saveLocal();render();}));root.querySelectorAll("[data-remove]").forEach(b=>b.addEventListener("click",()=>{state.cart=state.cart.filter(x=>x.product_id!==b.dataset.remove);saveLocal();render();}));root.querySelectorAll("[data-qty]").forEach(b=>b.addEventListener("click",()=>{const input=root.querySelector("#sfProductQty");if(input){const step=Number(input.step)||1;input.value=Math.max(Number(input.min)||step,Math.min(Number(input.max)||999,Number(input.value||step)+Number(b.dataset.qty)*step));}}));}
function addToCart(id,quantity=1,buyNow=false){const p=getProduct(id);if(!canOrderProduct(p)){notify(p&&Number(p.stock)>0?"This item is in preview until the store verifies its inventory.":"This product is currently unavailable.");return;}const qty=Math.max(quantityMinimum(p),Number(quantity)||quantityMinimum(p));const row=state.cart.find(x=>x.product_id===id);const next=(row?.quantity||0)+qty;if(next>Number(p.stock)){notify("The requested quantity is not available in stock.");return;}if(row)row.quantity=next;else state.cart.push({product_id:id,quantity:qty});saveLocal();notify("Added to your basket.");if(buyNow)location.href=pageUrl("checkout");else render();}
function changeCart(id,delta){
const row=state.cart.find(x=>x.product_id===id),p=getProduct(id);if(!row)return;
if(!p||Number(p.stock)<=0){state.cart=state.cart.filter(x=>x.product_id!==id);notify("An unavailable product was removed from your basket.");}
else{const minimum=quantityMinimum(p);row.quantity=Math.max(minimum,Math.min(Number(p.stock),Number(row.quantity)+delta));if(row.quantity===minimum&&delta<0)notify("Minimum order quantity is "+minimum+". Use Remove to clear this item.");}
saveLocal();render();
}
function toggleWish(id){state.wishlist=state.wishlist.includes(id)?state.wishlist.filter(x=>x!==id):[...state.wishlist,id];saveLocal();notify(state.wishlist.includes(id)?"Saved to wishlist.":"Removed from wishlist.");render();}
async function submitReturnRequest(e){e.preventDefault();const form=e.currentTarget,box=root.querySelector("#sfReturnStatus"),btn=root.querySelector("#sfReturnSubmit"),data=new FormData(form);box.textContent="Submitting your request…";btn.disabled=true;try{const result=await storefrontApi().submitReturnRequest(siteSlug,String(data.get("order")||"").trim(),String(data.get("phone")||"").trim(),String(data.get("reason")||"").trim(),String(data.get("notes")||"").trim());box.textContent="Request received. Reference: "+String(result?.id||"submitted")+". The store will review your request and contact you.";form.reset();}catch(err){box.textContent=err.message||"Your return request could not be submitted. Please check the order details.";}finally{btn.disabled=false;}}
function submitBulkQuickOrder(e){e.preventDefault();const inputs=[...root.querySelectorAll("[data-bulk-qty]")],status=root.querySelector("#sfBulkQuickStatus");let added=0,skipped=0;for(const input of inputs){const quantity=Number(input.value||0);if(!Number.isFinite(quantity)||quantity<=0)continue;const p=getProduct(input.dataset.bulkQty);if(!canOrderProduct(p)){skipped++;continue;}const minimum=Math.max(1,Number(p.attributes?.minimum_order_quantity||1)),existing=state.cart.find(x=>x.product_id===p.id),next=Number(existing?.quantity||0)+quantity;if(quantity<minimum||next>Number(p.stock)){skipped++;continue;}if(existing)existing.quantity=next;else state.cart.push({product_id:p.id,quantity});added++;}if(added){saveLocal();status.textContent=added+" product line(s) added to your basket."+(skipped?" "+skipped+" line(s) skipped because of minimum quantity or stock limits.":"");}else status.textContent="Enter a valid quantity for at least one product. Check minimum quantities and available stock.";}
function checkoutIdempotencyKey(payload){const fingerprint=JSON.stringify(payload),storageKey="hf-checkout-idempotency:"+siteSlug;let saved=null;try{saved=JSON.parse(sessionStorage.getItem(storageKey)||"null");}catch(_){}if(saved?.fingerprint===fingerprint&&/^[a-f0-9]{32}$/.test(String(saved.key||"")))return saved.key;if(!window.crypto?.getRandomValues)throw new Error("This browser cannot create a secure checkout key. Please use an updated browser.");const bytes=new Uint8Array(16);window.crypto.getRandomValues(bytes);const key=Array.from(bytes,b=>b.toString(16).padStart(2,"0")).join("");try{sessionStorage.setItem(storageKey,JSON.stringify({fingerprint,key}));}catch(_){throw new Error("Secure checkout retry protection needs browser session storage. Please enable it and try again.");}return key;}
async function submitOrder(e){e.preventDefault();const error=root.querySelector("#sfCheckoutError"),btn=root.querySelector("#sfPlaceOrder");if(!cartCount()){error.textContent="Your basket is empty.";return;}const blocked=state.cart.filter(x=>!canOrderProduct(getProduct(x.product_id)));if(blocked.length){error.textContent="Some basket items are still sample or unverified inventory. Remove them or wait until the store verifies the products.";return;}const form=new FormData(e.currentTarget),area=String(form.get("area")||"").trim(),fee=deliveryFeeForArea(area),minimum=minimumOrderForArea(area);if(cartTotal()<minimum){error.textContent="The minimum order is "+money(minimum)+".";return;}const customer={name:String(form.get("name")||"").trim(),phone:String(form.get("phone")||"").trim()};const shipping={name:customer.name,phone:customer.phone,address:String(form.get("address")||"").trim(),area,postcode:String(form.get("postcode")||"").trim()};const items=state.cart.map(x=>({product_id:x.product_id,quantity:x.quantity}));btn.disabled=true;btn.textContent="Submitting order…";error.textContent="";try{const notes=[String(form.get("notes")||"").trim(),form.get("substitution")?"Substitution preference: "+String(form.get("substitution")):""].filter(Boolean).join("\n").slice(0,2000);const idempotencyKey=checkoutIdempotencyKey({items,customer,shipping,notes});const result=await storefrontApi().placeOrder(siteSlug,items,customer,shipping,notes,idempotencyKey);try{sessionStorage.removeItem("hf-checkout-idempotency:"+siteSlug);}catch(_){}state.lastOrder=result;try{sessionStorage.setItem("hf-last-order:"+siteSlug,JSON.stringify(result));}catch(_){}state.cart=[];saveLocal();location.href=pageUrl("order-confirmation",{order:result.order_number});}catch(err){error.textContent=err.message||"Order could not be submitted. Please check your details and try again.";btn.disabled=false;btn.textContent="Place COD order";}}
async function trackOrder(e){e.preventDefault();const form=new FormData(e.currentTarget),box=root.querySelector("#sfTrackResult");box.textContent="Checking order…";try{const result=await storefrontApi().trackOrder(siteSlug,String(form.get("order")||"").trim(),String(form.get("phone")||"").trim());if(!result){state.lastTrackedOrder=null;box.innerHTML='<p role="alert">No order matched those details. Check the order number and phone number.</p>';return;}state.lastTrackedOrder=result;const statuses=["pending","processing","shipped","delivered"],current=statuses.indexOf(result.status);box.innerHTML='<div class="sf-content-panel"><span class="sf-kicker">ORDER '+esc(result.order_number)+'</span>'+(result.demo?'<span class="sf-kicker">DEMO TEST ORDER · NOT FOR FULFILMENT</span>':'')+'<h2>Current status: '+esc(result.status)+'</h2><p>Total '+money(result.total)+' · Payment '+esc(result.payment_status)+'</p><div class="sf-timeline">'+statuses.map((s,i)=>'<span class="'+(i<=current?"is-done":"")+'">'+s+'</span>').join("")+'</div><ul>'+result.items.map(x=>'<li>'+esc(x.product?.name||"Product")+' × '+esc(x.quantity)+' — '+money(x.line_total)+'</li>').join("")+'</ul>'+(result.items?.length?'<button type="button" class="sf-btn" data-reorder-tracked>Buy these items again</button>':"")+'</div>';bindDynamic();}catch(err){state.lastTrackedOrder=null;box.textContent=err.message||"Order lookup failed.";}}
function reorderTrackedOrder(){const items=state.lastTrackedOrder?.items||[],ready=[];for(const item of items){const id=item.product?.id,p=getProduct(id),quantity=Number(item.quantity||0);if(!p||quantity<=0||quantity<Number(p.attributes?.minimum_order_quantity||1))continue;const current=state.cart.find(x=>x.product_id===id),next=(current?.quantity||0)+quantity;if(next>Number(p.stock))continue;ready.push({id,quantity});}if(!ready.length){notify("The previous order's products are no longer available in the required quantities.");return;}for(const item of ready){const row=state.cart.find(x=>x.product_id===item.id);if(row)row.quantity+=item.quantity;else state.cart.push({product_id:item.id,quantity:item.quantity});}saveLocal();notify("Available items from your previous order were added to the basket.");location.href=pageUrl("cart");}
async function submitQuote(e){e.preventDefault();const form=e.currentTarget,status=root.querySelector("#sfBulkStatus"),button=root.querySelector("#sfBulkSubmit"),data=new FormData(form);if(preview){status.textContent="Quote submissions are disabled in private preview. Use the isolated QA workflow for acceptance testing.";return;}button.disabled=true;status.textContent="Saving your quote request…";try{const message=String(data.get("message")||"").trim(),items=message.split(/\r?\n/).map(line=>line.trim()).filter(Boolean).slice(0,100).map(description=>({description:description.slice(0,500)}));const business={company_name:String(data.get("company_name")||"").trim(),contact_name:String(data.get("contact_name")||"").trim(),phone:String(data.get("phone")||"").trim(),email:String(data.get("email")||"").trim(),business_type:String(data.get("business_type")||""),tax_id:String(data.get("tax_id")||"").trim()};if(!items.length)throw new Error("Add at least one product and quantity line.");const result=await storefrontApi().submitQuoteRequest(siteSlug,business,items,message.slice(0,2000));status.textContent=(result?.message||"Your quote request has been received.")+" Reference: "+(result?.quote_number||"saved");form.reset();}catch(err){status.textContent=err.message||"Your quote request could not be saved. Please try again.";}finally{button.disabled=false;}}
async function getPreviewToken(){return null;}
async function boot(){if(!siteSlug){throw new Error("A storefront site address is required.");}state.previewToken=await getPreviewToken();const data=await storefrontApi().loadStorefrontData(siteSlug,{token:state.previewToken,preview});state.website=data.website;state.pages=data.pages;state.documents=data.documents;state.categories=data.categories;state.products=data.products;state.deliveryZones=data.deliveryZones||[];state.priceTiers=data.priceTiers||[];state.page=params.get("page")||"home";if(!state.pages.some(p=>p.page_key===state.page)&&!state.documents.some(d=>d.page_key===state.page))state.page="home";if(state.website.status!=="published"||preview){let robots=document.querySelector('meta[name="robots"]');if(!robots){robots=document.createElement("meta");robots.name="robots";document.head.appendChild(robots);}robots.content="noindex,nofollow";}else{document.querySelector('meta[name="robots"]')?.remove();}loadLocal();render();}
boot().catch(err=>{console.error("Storefront load failed",err);root.innerHTML='<main class="sf-main"><div class="sf-empty"><h3>Storefront could not be opened</h3><p>'+esc(err.message||"Please try again later.")+'</p>'+(preview?'<a class="sf-btn" href="./admin/website-pages.html">Back to Website Pages</a>':'')+'</div></main>';});
})();

storefront.css:
:root{--sf-primary:#b94f35;--sf-ink:#273b32;--sf-paper:#fbf8f1;--sf-surface:#fff;--sf-accent:#e7a54b;--sf-muted:#77766f;--sf-line:rgba(39,59,50,.14);--sf-font:"DM Sans",sans-serif;--sf-display:"Playfair Display",serif;--sf-radius:18px;color-scheme:light}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--sf-paper);color:var(--sf-ink);font-family:var(--sf-font);font-size:15px;line-height:1.55}button,input,select,textarea{font:inherit}button,a{touch-action:manipulation}a{color:inherit;text-decoration:none}button{cursor:pointer}img{display:block;max-width:100%}.sf-loading{min-height:100vh;display:grid;place-content:center;justify-items:center;gap:12px;color:var(--sf-ink)}.sf-loading-mark{display:grid;place-items:center;width:54px;height:54px;border-radius:18px;background:var(--sf-primary);color:#fff;font-weight:900;letter-spacing:.1em}.sf-loading small{color:var(--sf-muted)}.sf-preview-bar{padding:9px 18px;background:#252b35;color:#fff;text-align:center;font-size:11px;letter-spacing:.04em}.sf-preview-bar strong{color:#f4d38b}.sf-announcement{background:var(--sf-ink);color:#fff;padding:8px 4vw;text-align:center;font-size:11px;font-weight:700;letter-spacing:.08em}.sf-header{position:sticky;top:0;z-index:20;background:color-mix(in srgb,var(--sf-paper) 92%,transparent);backdrop-filter:blur(16px);border-bottom:1px solid var(--sf-line)}.sf-header-inner{max-width:1320px;margin:auto;padding:15px 4vw;display:grid;grid-template-columns:auto minmax(180px,1fr) auto;align-items:center;gap:28px}.sf-brand{display:flex;align-items:center;gap:10px;min-width:0}.sf-brand-mark{display:grid;place-items:center;width:40px;height:40px;border-radius:13px;background:var(--sf-primary);color:#fff;font-weight:900;font-size:14px}.sf-brand-copy{display:grid;line-height:1.05}.sf-brand-copy strong{font-family:var(--sf-display);font-size:20px;letter-spacing:-.04em}.sf-brand-copy small{margin-top:5px;color:var(--sf-muted);font-size:9px;letter-spacing:.14em;text-transform:uppercase}.sf-search{display:flex;align-items:center;gap:10px;max-width:550px;width:100%;margin:auto;padding:0 15px;height:44px;background:var(--sf-surface);border:1px solid var(--sf-line);border-radius:999px}.sf-search input{border:0;outline:0;background