/* Editorial content and blog system */
.sf-rich-content{display:grid;gap:22px;line-height:1.75}
.sf-rich-block{padding:0 0 20px;border-bottom:1px solid var(--sf-line)}
.sf-rich-block:last-child{padding-bottom:0;border-bottom:0}
.sf-rich-block h2{margin:0 0 10px;font-family:var(--sf-display);font-size:clamp(21px,2.4vw,30px);letter-spacing:-.025em}
.sf-rich-block p{max-width:850px;margin:8px 0;color:var(--sf-muted);line-height:1.8}
.sf-rich-block ul{margin:10px 0;padding-left:22px;color:var(--sf-muted);line-height:1.9}
.sf-rich-cta{padding-top:10px}
.sf-blog-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px}
.sf-blog-card{overflow:hidden;border:1px solid var(--sf-line);border-radius:var(--sf-radius);background:var(--sf-surface);box-shadow:0 12px 30px rgba(28,38,32,.045)}
.sf-blog-card>a:first-child{display:block;overflow:hidden;background:var(--sf-paper)}
.sf-blog-card img{display:block;width:100%;aspect-ratio:16/9;object-fit:cover;transition:transform .35s ease}
.sf-blog-card:hover img{transform:scale(1.035)}
.sf-blog-card-body{padding:20px}
.sf-blog-card h2{margin:9px 0;font-family:var(--sf-display);font-size:clamp(20px,2.3vw,28px);line-height:1.14;letter-spacing:-.025em}
.sf-blog-card h2 a{color:var(--sf-ink);text-decoration:none}
.sf-blog-card p{color:var(--sf-muted);font-size:13px;line-height:1.75}
.sf-blog-meta{color:var(--sf-primary);font-size:10px;font-weight:900;letter-spacing:.1em;text-transform:uppercase}
.sf-text-link{display:inline-flex;margin-top:7px;color:var(--sf-primary);font-size:12px;font-weight:900;text-decoration:none}
.sf-blog-article{max-width:860px;margin:26px auto 0;padding:clamp(18px,4vw,44px);border:1px solid var(--sf-line);border-radius:var(--sf-radius);background:var(--sf-surface)}
.sf-blog-cover{display:block;width:100%;max-height:480px;aspect-ratio:16/9;object-fit:cover;border-radius:calc(var(--sf-radius) * .7);margin-bottom:24px}
.sf-blog-article>p{color:var(--sf-muted);font-size:16px;line-height:1.95;margin:18px 0}
.sf-blog-end{display:flex;gap:10px;flex-wrap:wrap;padding-top:20px;margin-top:24px;border-top:1px solid var(--sf-line)}
.sf-category-tile small{display:block;margin-top:7px;color:var(--sf-muted);font-size:11px;line-height:1.5}
@media(max-width:720px){.sf-blog-grid{grid-template-columns:1fr;gap:14px}.sf-blog-card-body{padding:16px}.sf-blog-article{padding:17px}.sf-blog-article>p{font-size:14px}}

/* Commerce-core refinements: accessible filters, operational product facts and bulk ordering. */
.sf-filter-controls{display:flex;align-items:center;gap:9px;flex-wrap:wrap}
.sf-product-facts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px 18px;margin:18px 0;padding:16px 18px;border:1px solid var(--sf-line);border-radius:14px;background:var(--sf-surface);list-style:none}
.sf-product-facts li{font-size:12px;color:var(--sf-muted);line-height:1.6}
.sf-product-facts strong{color:var(--sf-ink)}
.sf-help{color:var(--sf-muted);font-size:12px;line-height:1.7}
.sf-bulk-qty{width:94px;min-height:38px;padding:7px 9px;border:1px solid var(--sf-line);border-radius:9px;background:var(--sf-surface);color:var(--sf-ink)}
.sf-bulk-qty:disabled{opacity:.45}
.sf-table td small{color:var(--sf-muted);font-size:10px}
.sf-table tr[hidden]{display:none}
