/* Real Estate & Property — four distinct editorial systems */
.sf-realestate{--re-ink:#1e2d34;--re-accent:#a98755;--re-paper:#f6f3ed;--re-soft:#e9e0d3;--re-line:rgba(30,45,52,.14);color:var(--re-ink);background:var(--re-paper);padding:clamp(18px,3vw,42px);font-family:inherit}
