function filteredProducts(){let rows=activeProducts().slice();if(state.filters.category!=="all"){const cat=state.categories.find(c=>c.slug===state.filters.category);rows=rows.filter(p=>p.category_id===cat?.id);}if(state.filters.brand!=="all")rows=rows.filter(p=>String(p.attributes?.brand||"").trim()===state.filters.brand);if(state.filters.availability==="available")rows=rows.filter(p=>Number(p.stock)>0);if(state.filters.availability==="sold-out")rows=rows.filter(p=>Number(p.stock)<=0);if(state.filters.search){const q=state.filters.search.toLowerCase();rows=rows.filter(p=>[p.name,p.description,p.sku,p.attributes?.brand,p.attributes?.barcode,p.attributes?.origin,p.attributes?.farm_name,p.attributes?.pack_size,categoryName(p)].join(" ").toLowerCase().includes(q));}if(state.filters.sort==="price-low")rows.sort((a,b)=>Number(a.price)-Number(b.price));if(state.filters.sort==="price-high")rows.sort((a,b)=>Number(b.price)-Number(a.price));if(state.filters.sort==="name")rows.sort((a,b)=>a.name.localeCompare(b.name));if(state.filters.sort==="stock")rows.sort((a,b)=>Number(b.stock)-Number(a.stock));return rows;}
function shopPage(){const c=state.categories,brands=[...new Set(activeProducts().map(p=>String(p.attributes?.brand||"").trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b));return pageHead("THE FULL RANGE","Shop all products","Search by product, brand, SKU or origin, then narrow the catalogue with practical filters.")+'<div class="sf-toolbar"><div class="sf-filter-row"><button class="sf-chip '+(state.filters.category==="all"?"is-active":"")+'" data-filter-category="all">All</button>'+c.map(x=>'<button class="sf-chip '+(state.filters.category===x.slug?"is-active":"")+'" data-filter-category="'+esc(x.slug)+'">'+esc(x.name)+'</button>').join("")+'</div><div class="sf-filter-controls"><select class="sf-sort" id="sfBrandFilter" aria-label="Filter by brand"><option value="all">All brands</option>'+brands.map(x=>'<option value="'+esc(x)+'" '+(state.filters.brand===x?"selected":"")+'>'+esc(x)+'</option>').join("")+'</select><select class="sf-sort" id="sfAvailabilityFilter" aria-label="Filter by availability"><option value="all">All availability</option><option value="available" '+(state.filters.availability==="available"?"selected":"")+'>In stock</option><option value="sold-out" '+(state.filters.availability==="sold-out"?"selected":"")+'>Sold out</option></select><select class="sf-sort" id="sfSort" aria-label="Sort products"><option value="featured">Featured</option><option value="price-low">Price: low to high</option><option value="price-high">Price: high to low</option><option value="name">Name</option><option value="stock">Stock availability</option></select></div></div><div id="sfProductResults"><p class="sf-help">'+filteredProducts().length+' product(s) found</p>'+productGrid(filteredProducts())+'</div>';}
function categoryPage(){const slug=params.get("category")||"",cat=state.categories.find(c=>c.slug===slug);const rows=cat?state.products.filter(p=>p.category_id===cat.id):[];return pageHead("SHOP BY CATEGORY",cat?.name||"Category not found",cat?"Explore products in this collection.":"Choose a category from the shop page.",'<a class="sf-btn secondary" href="'+pageUrl("shop")+'">All products</a>')+productGrid(rows);}
function searchPage(){const q=params.get("q")||"";state.filters.search=q;return pageHead("SEARCH THE STORE","Search results",q?'Results for “'+q+'”':'Search the product catalogue.')+'<form class="sf-toolbar" id="sfSearchForm"><input class="sf-sort" style="flex:1;min-width:180px" name="q" value="'+esc(q)+'" placeholder="Search products, categories…" aria-label="Search products"><button class="sf-btn">Search</button></form>'+productGrid(filteredProducts());}
function productTierMarkup(p){const tiers=state.priceTiers.filter(t=>t.product_id===p.id).sort((a,b)=>Number(a.minimum_quantity)-Number(b.minimum_quantity));return tiers.length?'<div class="sf-content-panel" style="margin-top:16px"><h3>Volume pricing</h3><ul>'+tiers.map(t=>'<li>Buy '+esc(t.minimum_quantity)+'+ · '+money(t.unit_price)+' / '+esc(p.unit||"unit")+(t.label?' · '+esc(t.label):"")+'</li>').join("")+'</ul><small>Applicable quantity discount is calculated automatically in your basket and confirmed by the server at checkout.</small></div>':"";}
function productPage(){const p=getProduct(params.get("product"));if(!p)return '<div class="sf-empty"><h3>Product not found</h3><p>This product may be unavailable or removed from the catalogue.</p><a class="sf-btn" href="'+pageUrl("shop")+'">Back to shop</a></div>';const img=imageUrl(p),attrs=p.attributes||{},qtyStep=quantityStep(p),qtyMin=quantityMinimum(p),facts=[["Barcode",attrs.barcode],["Pack size",attrs.pack_size],["Origin",attrs.origin],["Grade",attrs.grade],["Farm / producer",attrs.farm_name],["Expiry date",attrs.expiry_date]].filter(x=>String(x[1]||"").trim()),factsHtml=facts.length?'<ul class="sf-product-facts">'+facts.map(x=>'<li><strong>'+esc(x[0])+'</strong>: '+esc(x[1])+'</li>').join("")+'</ul>':"";return '<div class="sf-product-detail"><div class="sf-gallery-main">'+(img?'<img src="'+esc(img)+'" alt="'+esc(p.name)+'">':'')+'</div><div class="sf-product-copy"><span class="sf-kicker">'+esc(categoryName(p))+'</span><h1>'+esc(p.name)+'</h1><div class="sf-product-price">'+money(p.price)+' <small style="font-size:12px;color:var(--sf-muted)">/ '+esc(p.unit||"piece")+'</small></div><p>'+esc(p.description||"Carefully selected for your everyday needs.")+'</p><p><span class="sf-status-pill">'+(state.website.settings?.demo_catalog?"Demo product · test orders enabled":canOrderProduct(p)?"In stock":Number(p.stock)>0?"Preview only — inventory verification required":"Currently unavailable")+'</span>　<small>SKU: '+esc(p.sku||"—")+'</small></p>'+(p.attributes?.minimum_order_quantity?'<p>Minimum order: '+qtyMin+' '+esc(p.unit||"units")+'</p>':'')+factsHtml+productTierMarkup(p)+'<div class="sf-product-actions"><label class="sf-qty"><button type="button" data-qty="-1">−</button><input id="sfProductQty" type="number" min="'+qtyMin+'" step="'+qtyStep+'" max="'+Math.max(qtyMin,Number(p.stock))+'" value="'+qtyMin+'"><button type="button" data-qty="1">+</button></label><button class="sf-btn" data-add="'+esc(p.id)+'" '+(!canOrderProduct(p)?"disabled":"")+'>'+ (state.website.temp