function cartRows(){return state.cart.map(item=>{const p=getProduct(item.product_id);if(!p)return "";const unitPrice=priceForProduct(p,item.quantity),step=quantityStep(p),minimum=quantityMinimum(p);return '<div class="sf-cart-row"><a href="'+pageUrl("product",{product:p.id})+'">'+(imageUrl(p)?'<img src="'+esc(imageUrl(p))+'" alt="">':'<div class="sf-product-media"></div>')+'</a><div><h3><a href="'+pageUrl("product",{product:p.id})+'">'+esc(p.name)+'</a></h3><small>'+money(unitPrice)+' / '+esc(p.unit||"piece")+(unitPrice<Number(p.price)?' · volume price applied':"")+'</small><div class="sf-cart-controls"><button data-cart-qty="-1" data-product="'+esc(p.id)+'">−</button><input class="sf-cart-quantity" type="number" data-cart-input data-product="'+esc(p.id)+'" min="'+minimum+'" max="'+Number(p.stock)+'" step="'+step+'" value="'+Number(item.quantity)+'" aria-label="Quantity for '+esc(p.name)+'"><button data-cart-qty="1" data-product="'+esc(p.id)+'">+</button><button data-remove="'+esc(p.id)+'" aria-label="Remove product">Remove</button></div></div><strong>'+money(unitPrice*Number(item.quantity))+'</strong></div>';}).join("");}
function cartPage(){if(!cartCount())return '<div class="sf-empty"><h3>Your basket is taking a breather</h3><p>Find something good and add it to your basket.</p><a class="sf-btn" href="'+pageUrl("shop")+'">Start shopping</a></div>';return pageHead("YOUR SELECTION","Your basket","Review quantities and make sure everything is just right.")+'<div class="sf-cart-layout"><div class="sf-cart-list">'+cartRows()+'</div>'+summaryCard(false)+'</div>';}
function summaryCard(checkout=false){const area=checkout?(state.checkoutArea||""):"",delivery=deliveryFeeForArea(area),total=cartTotal();return '<aside class="sf-summary"><h3>Order summary</h3><div class="sf-summary-line"><span>Items ('+cartCount()+')</span><b>'+money(total)+'</b></div><div class="sf-summary-line"><span>Delivery estimate</span><b data-summary-delivery>'+money(delivery)+'</b></div><div class="sf-summary-total"><span>Total</span><strong data-summary-total>'+money(total+delivery)+'</strong></div><small data-summary-note style="color:var(--sf-muted)">'+(area?"Delivery fee calculated for selected area.":"Default delivery fee applies unless a configured zone is selected.")+'</small><div style="margin-top:18px">'+(checkout?'<button class="sf-btn" type="submit" form="sfCheckoutForm" style="width:100%">Place COD order →</button>':'<a class="sf-btn" style="width:100%" href="'+pageUrl("checkout")+'">Continue to checkout →</a>')+'</div><p><a href="'+pageUrl("shop")+'">← Continue shopping</a></p></aside>';}
