function orderConfirmation(){const order=state.lastOrder||(()=>{try{return JSON.parse(sessionStorage.getItem("hf-last-order:"+siteSlug)||"null");}catch(_){return null;}})();if(!order)return '<div class="sf-empty"><h3>No recent order in this browser</h3><p>Use Track Order to look up an existing order.</p><a class="sf-btn" href="'+pageUrl("order-tracking")+'">Track an order</a></div>';return '<div class="sf-content-panel" style="text-align:center;padding:clamp(28px,6vw,70px)"><span style="font-size:46px">✓</span><span class="sf-kicker">ORDER RECEIVED</span>'+(order.demo?'<span class="sf-status-pill">DEMO ORDER · TEST ONLY</span>':'')+'<h1 style="font-family:var(--sf-display);font-size:clamp(34px,5vw,54px)">Thank you. We have your order.</h1><p>Your order number is</p><h2 style="font-size:26px;color:var(--sf-primary)">'+esc(order.order_number)+'</h2><p>Total: <strong>'+money(order.total)+'</strong> · Cash on delivery</p><p>Keep this order number and your phone number to track progress.</p><a class="sf-btn" href="'+pageUrl("order-tracking",{order:order.order_number})+'">Track your order</a></div>';}
